import { useEffect, useMemo, useState } from 'react';
import type { FormEvent, ReactNode } from 'react';
import { Activity, ArrowDown, ArrowRight, ArrowUpRight, Bell, Check, CheckCircle2, ChevronDown, ChevronRight, ChevronsUpDown, Circle, CircleHelp, Clock3, Database as DatabaseIcon, Download, Filter, Flag, FolderKanban, Globe2, Handshake, LayoutDashboard, ListFilter, Loader2, Menu, MessageSquare, MoreHorizontal, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, TrendingUp, TriangleAlert, Users, X } from 'lucide-react';
import { Button } from './components/ui/button';
import { Dialog } from './components/ui/dialog';
import type { Coverage, Database, Filters, Health, Movement, SourceRecord, UseCase } from './models';
import { themes } from './models';
